请对以下 case 进行三维加权评分。

=== case_id ===
Case-18-carpool-345

=== 用户原始指令 (query.txt) ===
拼车卡显示同行3人省20块,点一下导航到地铁,日历有9点会议,已出发

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "拼车卡显示同行3人省20块,点一下导航到地铁,日历有9点会议,已出发",
  "size": "2x4",
  "eventCandidates": [
    {
      "call": "clickToIntent",
      "args": {
        "intentName": "StartNavigate",
        "params": {
          "dstLocation": {
            "latitude": "22.3193",
            "longitude": "114.1694"
          },
          "trafficpe": "Bus"
        }
      }
    }
  ],
  "dataModel": {
    "value": {
      "carpool": {
        "title": "拼车已出发",
        "status": "已出发",
        "riderCount": 3,
        "saveAmount": 20,
        "route": "导航到地铁",
        "actionText": "去地铁"
      },
      "data": {
        "calendar": {
          "items": [
            {
              "entityName": "calendar",
              "entityId": "carpool-345-meeting",
              "title": "会议",
              "dtStart": "09:00",
              "dtEnd": "10:00",
              "eventLocation": "办公室"
            }
          ]
        }
      },
      "asset": {
        "carpoolGlyph": "resources/base/media/icon_car.png",
        "calendarGlyph": "resources/base/media/icon_schedule.png"
      },
      "state": {
        "loading": false
      }
    }
  },
  "assetCandidates": [
    {
      "assetRef": "carpool_glyph",
      "src": "resources/base/media/icon_car.png",
      "use": "carpool trip glyph",
      "description": "车辆图标，用于拼车出行卡片的主视觉符号。",
      "bindTo": "/asset/carpoolGlyph",
      "static": true
    },
    {
      "assetRef": "calendar_glyph",
      "src": "resources/base/media/icon_schedule.png",
      "use": "calendar meeting glyph",
      "description": "日程图标，用于提示当天会议安排。",
      "bindTo": "/asset/calendarGlyph",
      "static": true
    }
  ]
}

